-- Forecast the parts mix for problem P01, every region, next 12 weeks.
-- Target: rolling 4-week attach rate per candidate part (share of jobs using it).
-- Covariates known ahead: forecast temperature, install-base units at risk.
-- Generated by bigquery/make_sql.py.

WITH weekly AS (
  SELECT
    j.week, j.region, j.jobs,
    SUM(IF(u.part_id = 'CAP-45-5', u.uses, 0)) AS cap_45_5,
    SUM(IF(u.part_id = 'CON-30A', u.uses, 0)) AS con_30a,
    SUM(IF(u.part_id = 'FM-1/4HP', u.uses, 0)) AS fm_1_4hp,
    SUM(IF(u.part_id = 'HSK-01', u.uses, 0)) AS hsk_01,
    SUM(IF(u.part_id = 'R410-25', u.uses, 0)) AS r410_25,
    SUM(IF(u.part_id = 'TXV-3T', u.uses, 0)) AS txv_3t
  FROM trunk.jobs_weekly AS j
  LEFT JOIN trunk.part_usage_weekly AS u
    USING (week, region, problem_code)
  WHERE j.problem_code = 'P01'
  GROUP BY j.week, j.region, j.jobs
),
rolling AS (
  SELECT
    week, region,
    SAFE_DIVIDE(SUM(cap_45_5) OVER w, SUM(jobs) OVER w) AS cap_45_5,
    SAFE_DIVIDE(SUM(con_30a) OVER w, SUM(jobs) OVER w) AS con_30a,
    SAFE_DIVIDE(SUM(fm_1_4hp) OVER w, SUM(jobs) OVER w) AS fm_1_4hp,
    SAFE_DIVIDE(SUM(hsk_01) OVER w, SUM(jobs) OVER w) AS hsk_01,
    SAFE_DIVIDE(SUM(r410_25) OVER w, SUM(jobs) OVER w) AS r410_25,
    SAFE_DIVIDE(SUM(txv_3t) OVER w, SUM(jobs) OVER w) AS txv_3t
  FROM weekly
  WINDOW w AS (PARTITION BY region ORDER BY week ROWS BETWEEN 3 PRECEDING AND CURRENT ROW)
),
-- History rows carry the targets; the 12 future rows carry NULL targets and
-- the covariates, which is how AI.FORECAST knows the horizon's conditions.
data AS (
  SELECT
    wx.week, wx.region,
    r.cap_45_5, r.con_30a, r.fm_1_4hp, r.hsk_01, r.r410_25, r.txv_3t,
    wx.avg_temp_f,
    ib.units_at_risk
  FROM trunk.weather_weekly AS wx
  JOIN trunk.install_base_weekly AS ib
    ON ib.week = wx.week AND ib.region = wx.region AND ib.problem_code = 'P01'
  LEFT JOIN rolling AS r
    ON r.week = wx.week AND r.region = wx.region
)
SELECT *
FROM AI.FORECAST(
  TABLE data,
  model => 'TimesFM 3.0',
  timestamp_col => 'week',
  id_cols => ['region'],
  target_cols => ['cap_45_5', 'con_30a', 'fm_1_4hp', 'hsk_01', 'r410_25', 'txv_3t'],
  future_covariate_cols => ['avg_temp_f', 'units_at_risk'],
  horizon => 12,
  confidence_level => 0.8       -- 80% interval: the 10th and 90th percentiles
);
